    let page = Number(java.get("page"))
    let uidList = getUserIdCache()
    if (!uidList) [uidList, novels] = getUserIdOnline()

    if(uidList.length === 0 || uidList.length >=2 ) return novels
    else if(uidList.length === 1 ) {
