            checkSettings(settings)
        } else {
            checkSettings(settings)
            msg = `\n\n${statusMsg(status)}　${settingsName[settingName]}\n\n${getSettingStatus(settingName)}`
        }
        try {source.refreshExplore()} catch (e) {}
    } else {
        msg = `\n\n${statusMsg(status)}　${settingsName[settingName]}`
