}
const settingsName = Object.assign({},
    novelSettingsName,
    discoverSettingsName,
    menuSettingsName
)
const settingsOptionsNames = {
    "PIC_SOURCE": {
        "PixivShojo": "📄 PixivShojo",
        "PixivCat": "🐱 PixivCat",
    },
    "PIC_LINK": {
        "PixivShojo": "📄 PixivShojo",
