    // return `${pxImgUrl.replace(`i.pximg.net`, `i.pximg.nl`)}`
}
function urlPxImgUrlPixivShojo(pxImgUrl) {
    return `${pxImgUrl.replace(`i.pximg.net`, `proxy.pixiv.shojo.cn`)}`
}
function urlPxImgUrlCloudFlare(pxImgUrl) {
