function urlIP(url) {
    const {java, cache} = this
    url = url.replace("http://", "https://").replace("www.pixiv.net", "210.140.139.155")
    let headers = {
        "User-Agent": this.getWebViewUA(),
        "X-Requested-With": "XMLHttpRequest",
        "Host": "www.pixiv.net",
        "Referer": "https://www.pixiv.net/"
    }
