}

function updateSourceLink(){
    const {java, source} = this
    let sourceName
    if (source.bookSourceUrl.includes("pixiv")) sourceName = "pixiv"
    else if (source.bookSourceUrl.includes("furrynovel")) sourceName = "linpx"

